const sql=`SELECT current_setting('server_version_num') AS engine,(SELECT count(*)::int FROM supabase_migrations.schema_migrations) AS ledger,(SELECT max(version::text) FROM supabase_migrations.schema_migrations) AS latest,(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.tablename,p.policyname) FROM pg_policies p WHERE p.schemaname='public' AND p.policyname IN('bu_write','tg_admin') AND p.tablename IN('business_units','tenant_groups')) AS policies,(SELECT jsonb_build_object('owner',proowner::text,'acl',proacl::text,'config',proconfig,'arguments',pg_get_function_identity_arguments(oid),'result',pg_get_function_result(oid),'body_md5',md5(pg_get_functiondef(oid))) FROM pg_proc WHERE oid='public.seed_default_tenant_groups(uuid)'::regprocedure) AS seed,(SELECT coalesce(jsonb_agg(jsonb_build_object('relation',n.nspname||'.'||c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default_hash',md5(coalesce(pg_get_expr(d.adbin,d.adrelid),''))) ORDER BY c.oid,a.attnum),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relname IN('tenant_members','tenants','business_units','tenant_groups','tenant_group_presets','tenant_group_roles','rbac_roles','bu_group_assignments')) AS consumed_columns,(SELECT coalesce(jsonb_agg(n.nspname||'.'||p.proname ORDER BY p.oid),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='private' AND p.proname IN('fvi_active_structure_admin','fvi_structure_write_context','fvi_bu_structure_guard','fvi_group_structure_guard','fvi_seed_missing_group_presets') OR n.nspname='public' AND p.proname='seed_tenant_group_presets_for_bu') AS collisions`;
