await writeFile('docs/evidence/FVI_STRUCTURE_WRITE_CURRENT_CATALOG_2026-10-05-'+Date.now()+'.json',JSON.stringify({at:new Date().toISOString(),results,noSqlApplied:true},null,2),{flag:'wx'});console.log(JSON.stringify(results));
